#!/usr/bin/env python3
"""For each of the 12 Borels (chambers) of gs(2): is n+ generated by its two simple root vectors?
In the text: Subsec. 4.1 (the four Chevalley generators generate 11 of 14, for each of the 12 Borels)."""
import numpy as np, sys
from f2lin import rref
from lalg import *
from scan import chambers
H = [NAMES.index('u1d1'), NAMES.index('u2d2')]
E = np.eye(N, dtype=np.int64)
def gen_dim(gens):
    S = [E[g] for g in gens]
    while True:
        R, _ = rref(np.array(S)); S = list(R.astype(np.int64)); new = []
        for a in S:
            for b in S: new.append(np.einsum('i,j,ijk->k', a, b, CL.astype(np.int64)) & 1)
        R2, _ = rref(np.array(S + new))
        if len(R2) == len(S): return len(S)
        S = list(R2.astype(np.int64))
for pos in chambers():
    roots = [k for k in pos if k < NG]
    W = {k: tuple(WTS[k]) for k in roots}
    simple = [k for k in roots if not any(tuple(np.subtract(W[k], W[j])) in W.values() for j in roots if j != k)]
    neg = [j for j in range(NG) if j not in H and j not in roots]
    negs = [j for j in neg if tuple(-np.array(WTS[j])) in [W[k] for k in simple]]
    print('simple', [NAMES[k] for k in simple], ' n+ gen by simple: %d of %d;  whole algebra by the 4: %d of %d'
          % (gen_dim(simple), len(roots), gen_dim(simple + negs), NG))
